function [kind] = guid_kind(mode)
%GUID_KIND  The guidance a controller state flies: 0 nadir, 1 target, 2 slew, 4 Sun (states as adcs_params.h:
%   3 target_fine, 4 slew_fine, 9 sun_mtq, 10 sun_fine).
%   mode: int (passed a whole number)
%   returns kind: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    kind = 0;
    if (mode == 3)
        kind = 1;
    elseif (mode == 4)
        kind = 2;
    elseif ((mode == 9) || (mode == 10))
        kind = 4;
    else
        kind = 0;
    end
end
